async function loadGeneratedLocale(code){if(code==='fr'||!localeCodes.includes(code)||generatedLocales.has(code))return;try{const res=await fetch('./locales/'+encodeURIComponent(code)+'.json?v='+V);if(!res.ok)throw Error('pack');const raw=await res.text();if(raw.length>3000000)throw Error('size');const p=JSON.parse(raw);if(p.locale!==code||p.machineTranslated!==true||!p.ui||typeof p.ui!=='object'||Array.isArray(p.ui)||!Array.isArray(p.lessons)||p.lessons.length!==academyLessons.length)throw Error('schema');const entries=Object.entries(p.ui);if(entries.length>20000||entries.some(([k,v])=>!k||typeof v!=='string'||!v.trim()||v.length>5000))throw Error('entries');const rows=p.lessons.map((row,i)=>{const original=academyLessons[i];if(!Array.isArray(row)||row.length!==original.length||!row.slice(0,7).every(x=>typeof x==='string'&&x.trim())||JSON.stringify(row.slice(7))!==JSON.stringify(original.slice(7)))return original;return row[4]===row[5]?original:row});generatedLessons.set(code,rows);generatedLocales.set(code,new Map(entries));}catch(e){console.warn('Locale pack unavailable; using built-in translations',code,e)}}
function translateLabel(value){const reviewed=window.VEKAID_REVIEWED_LAB?.[locale]?.[value];if(reviewed)return reviewed;const idx=localeCodes.indexOf(locale);if(idx>=4){const i=extraIndex.get(value);return (i===undefined?undefined:extraPacks[locale][i])||generatedLocales.get(locale)?.get(value)||value;}const direct=dictionary.get(value);if(direct)return direct[idx]||value;if(idx<=0)return value;let activity=value.match(/^(notes|studio|audit)\s*:\s*(\d+)$/i);if(activity){const labels={notes:['notes','notes','Notizen','笔记'],studio:['studio','studio','Studio','工作室'],audit:['audit','audit','Audit','审计']};return labels[activity[1].toLowerCase()][idx]+' : '+activity[2]}let count=value.match(/^(\d+) fiches à réviser$/);if(count)return [value,count[1]+' cards to review',count[1]+' Lernkarten zu wiederholen',count[1]+' 张待复习卡片'][idx];count=value.match(/^(\d+) \/ (\d+) étudiées · pas une certification$/);if(count)return [value,count[1]+' / '+count[2]+' studied · not a certification',count[1]+' / '+count[2]+' gelernt · keine Zertifizierung',count[1]+' / '+count[2]+' 已学习 · 非认证'][idx];let m=value.match(/^(\d+) observation\(s\) manuelle\(s\) sur 7 · aucun quota réel consulté\.$/);if(m)return [value,m[1]+' of 7 manual observations · no live quota checked',m[1]+' von 7 manuellen Beobachtungen · keine Live-Kontingente geprüft',m[1]+'/7 项手动记录 · 未查询实时配额'][idx];m=value.match(/^(\d+)\/3 sources disponibles · aucune activité réelle attestée$/);if(m)return [value,m[1]+'/3 sources available · no actual activity verified',m[1]+'/3 Quellen verfügbar · keine tatsächliche Aktivität nachgewiesen',m[1]+'/3 个来源可用 · 实际活动未经验证'][idx];return generatedLocales.get(locale)?.get(value)||value}
