function localize(root){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest('script,style,textarea,input,[contenteditable],#aclist,#acanswers,#daily-feed,[data-vek-user-content]'))continue;if(node.parentElement?.closest('#tl')&&!node.parentElement.closest('.v23-empty'))continue;const old=translatedNodes.get(node),raw=old&&node.nodeValue===old.rendered?old.raw:node.nodeValue;const key=raw.trim().replace(/\s+/g,' ');const localized=translateLabel(key);if(localized===key&&!old)continue;const rendered=raw.replace(/\S[\s\S]*\S|\S/,()=>localized);translatedNodes.set(node,{raw,rendered});if(node.nodeValue!==rendered)node.nodeValue=rendered}for(const el of root.querySelectorAll?.('[placeholder],[aria-label]')||[]){for(const a of ['placeholder','aria-label']){if(!el.hasAttribute(a))continue;const key='data-vek-source-'+a,previous=el.getAttribute(key),current=el.getAttribute(a),last=el.getAttribute(key+'-rendered'),original=previous!==null&&current===last?previous:current;if(dictionary.has(original)||extraIndex.has(original)||generatedLocales.get(locale)?.has(original)){el.setAttribute(key,original);const v=translateLabel(original);el.setAttribute(key+'-rendered',v);if(el.getAttribute(a)!==v)el.setAttribute(a,v)}}}}
function languagePicker(b){const section=document.createElement('section');section.className='v23-section';const label=document.createElement('label');label.className='v23-section-title';label.htmlFor='vek-language';label.textContent='Préférences de langue';const select=document.createElement('select');select.id='vek-language';select.className='v23-search';for(const value of localeCodes){const option=document.createElement('option');option.value=value;let name=value;try{name=new Intl.DisplayNames([value],{type:'language'}).of(value)||value}catch{}option.textContent=name+' · '+(value==='fr'?'original':'machine translation / traduction automatique');select.append(option)}select.value=locale;select.onchange=async()=>{select.disabled=true;try{localStorage.setItem('vekaid.locale',select.value)}catch{}locale=select.value;document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';await loadGeneratedLocale(locale);localize(document.body);you()};const note=document.createElement('p');note.className='v23-note';note.textContent='Les cours, actualités et anciens modules peuvent rester en français.';section.append(label,select,note);b.prepend(section);localize(section)}
