async function work(){const t=await tickets();const b=layer('Work','Missions structurées comme des tickets techniques','<div class="v23-actions"><button class="v23-btn primary" id="newt">Nouvelle mission</button><button class="v23-btn" id="studio23">Ouvrir Studio</button><button class="v23-btn" id="release23">Vérifier la release</button><button class="v23-btn" id="oldm">Missions historiques</button></div><section class="v23-section"><p class="v23-section-title">Mes missions</p><div class="v23-group" id="tl"></div></section><div id="tf"></div>');$('#oldm',b).onclick=()=>{resetLayers();window.tab?.('missions')};$('#newt',b).onclick=()=>form(b,{});$('#studio23',b).onclick=studio;$('#release23',b).onclick=releaseCenter;const root=$('#tl',b);if(!t.length)root.innerHTML='<div class="v23-empty"><strong>Aucune mission enregistrée</strong><p>Ajoute une tâche avec un résultat attendu.</p><button class="v23-btn primary" id="first-ticket">Créer une mission</button></div>';if(!t.length)$('#first-ticket',root).onclick=()=>form(b,{});t.sort((a,z)=>String(z.createdAt).localeCompare(String(a.createdAt))).forEach(x=>{const r=document.createElement('button');r.className='v23-row';r.innerHTML='<strong>'+esc(x.title)+'</strong><small>'+esc(x.legacy?'Mission historique':x.outcome||x.context||'Sans résultat attendu')+' · '+(x.status==='done'?'terminée':'active')+'</small>';r.onclick=()=>{if(x.legacy){resetLayers();window.tab?.('missions')}else form(b,x)};root.append(r)})}
function form(b,t){const host=$('#tf',b);host.innerHTML=`<form id="f23" novalidate>
<section class="v23-form-chunk"><p class="v23-section-title">Définir la mission</p><div class="v23-field"><label>Titre</label><input name="title" value="${esc(t.title||'')}" autocomplete="off"><span class="v23-field-hint">Un titre court et actionnable.</span></div><div class="v23-field"><label>Contexte</label><textarea name="context">${esc(t.context||'')}</textarea></div><div class="v23-field"><label>Résultat attendu</label><textarea name="outcome">${esc(t.outcome||'')}</textarea></div></section>
<section class="v23-form-chunk"><p class="v23-section-title">Encadrer l’exécution</p><div class="v23-field"><label>Contraintes</label><textarea name="constraints">${esc(t.constraints||'')}</textarea></div><div class="v23-field"><label>Critères d’acceptation</label><textarea name="acceptance">${esc(t.acceptance||'')}</textarea></div><div class="v23-field"><label>Tests</label><textarea name="tests">${esc(t.tests||'')}</textarea></div></section>
<section class="v23-form-chunk"><p class="v23-section-title">Fermer la boucle</p><div class="v23-field"><label>Preuve / résultat</label><textarea name="proof">${esc(t.proof||'')}</textarea></div></section>
<div class="v23-actions"><button type="submit" class="v23-btn primary">Enregistrer la mission</button>${t.id?'<button type="button" class="v23-btn" id="done23">'+(t.status==='done'?'Réouvrir':'Terminer')+'</button>':''}</div></form>`;host.scrollIntoView({block:'start',behavior:'instant'});enhanceVekForm($('#f23',b),{requiredName:'title',readyText:'Titre prêt',errorText:'Ajoute un titre avant d’enregistrer'});$('#f23',b).onsubmit=async e=>{e.preventDefault();if(e.currentTarget.__vekValidate&&!e.currentTarget.__vekValidate())return;const done=submitState(e.currentTarget,'Enregistrement…');const f=new FormData(e.currentTarget),o={...t,id:t.id||uid(),title:String(f.get('title')).trim(),context:String(f.get('context')).trim(),outcome:String(f.get('outcome')).trim(),constraints:String(f.get('constraints')).trim(),acceptance:String(f.get('acceptance')).trim(),tests:String(f.get('tests')).trim(),proof:String(f.get('proof')).trim(),status:t.status||'todo',createdAt:t.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};try{await put('tickets',o);done(true);setTimeout(()=>{resetLayers();work()},480)}catch(err){done(false)}};$('#done23',b)?.addEventListener('click',async()=>{await put('tickets',{...t,status:t.status==='done'?'todo':'done',updatedAt:new Date().toISOString()});resetLayers();work()})}
const skills=['Git','JavaScript','Sécurité','DevOps','Linux','Réseaux','Python','Active Directory','Docker','Cloud'];

const academyLessons=[["Support IT","Diagnostic méthodique","Identifier le symptôme, reproduire, isoler une cause, tester une correction et documenter la preuve. Ne pas confondre hypothèse et résultat.","Un poste ne résout plus les noms DNS. Quelle première démarche ?","Comparer résolution DNS et connectivité IP avant de modifier la configuration.","Réinstaller immédiatement Windows.","Sur un lab, documenter ipconfig, ping et nslookup, puis expliquer les résultats."],["Réseaux","Frontières de confiance","Cartographier actifs, flux, réseau et frontières de confiance. Appliquer le moindre privilège.","Un service interne doit-il être accessible à tous ?","Non, limiter les accès aux flux nécessaires.","Oui, si son adresse est inconnue.","Dessiner un réseau client, serveur DNS et pare-feu avec les flux autorisés."],["Linux","Permissions et exploitation","Limiter les droits, contrôler les services, conserver des journaux sans secrets et tester la restauration.","Comment exécuter un service ?","Avec un compte dédié aux droits minimaux.","Toujours en root.","Dans une VM, examiner les droits et les journaux d’un service."],["Git","Revue et non-régression","Vérifier la branche, conserver les preuves, relire les changements et distinguer succès CI et déploiement.","Une CI verte prouve-t-elle que la production est à jour ?","Non, vérifier séparément le déploiement.","Oui, toujours.","Créer une branche, un commit et une procédure de retour arrière dans un dépôt de test."],["Architecture","Choisir le bon profil","Site vitrine : SEO et accessibilité. PWA : cache et stockage. SaaS : API, authentification et isolation. Cloud : IAM et réseau. Mobile : cycle de vie.","Une PWA statique nécessite-t-elle immédiatement OAuth ?","Non, réévaluer selon les besoins et l’architecture.","Oui, dans tous les cas.","Dessiner deux architectures, site statique et SaaS, puis justifier leurs différences."],["Sécurité","Authentification et autorisation","Refuser par défaut. Vérifier les droits côté serveur pour chaque objet. Sessions révocables, MFA selon risque, OAuth avec PKCE et redirections strictes.","CORS remplace-t-il une vérification d’autorisation ?","Non, chaque action doit être autorisée côté serveur.","Oui, si le domaine est connu.","Définir les tests d’accès croisé entre deux comptes fictifs."],["Sécurité","Entrées et injections","Validation serveur par schéma, limites de taille, requêtes paramétrées, encodage contextuel, CSP restrictive. Éviter le shell avec des entrées utilisateur.","Comment prévenir les injections SQL ?","Utiliser des requêtes paramétrées et valider les entrées.","Masquer les erreurs uniquement.","Écrire un test de rejet d’entrée invalide dans un lab local."],["Sécurité","Secrets et dépendances","Secrets hors frontend et dépôt, rotation, TLS, dépendances verrouillées et auditées, CI à permissions minimales.","Une clé secrète dans JavaScript public est-elle protégée ?","Non, elle est accessible au client.","Oui, si le code est minifié.","Inventorier les dépendances et rechercher les secrets dans un projet de test."],["DevOps","Production et rollback","Tests unitaires, intégration, parcours complets, performance, monitoring et restauration testée. Vérifier la livraison indépendamment de CI.","Que préparer avant une release ?","Un rollback documenté et des critères de validation.","Seulement un nouveau numéro de version.","Rédiger une checklist de déploiement avec test de retour arrière."],["Cloud","IAM et résilience","Réseau privé, IAM minimal, secrets protégés, infrastructure reproductible, sauvegardes et restauration.","Une sauvegarde non restaurée est-elle une preuve de reprise ?","Non, tester la restauration.","Oui, si le fichier existe.","Dessiner une architecture avec accès minimal et scénario de panne."],["UX","Direction artistique","Créer des tokens, une grille, une typographie, des formes et des états propres au produit. Éviter les gradients automatiques et cartes imbriquées.","Comment éviter une interface générique ?","Construire une identité cohérente avec le produit.","Ajouter davantage de gradients et badges.","Auditer trois écrans et proposer des corrections justifiées."],["Mobile","Motion et ergonomie","Transitions interruptibles, reduced motion, focus visible, contraste, zoom accessible, safe areas et clavier iOS. Tester lancement froid et chaud.","Faut-il bloquer globalement le zoom ?","Non, préserver le zoom d’accessibilité.","Oui, pour tout utilisateur.","Tester navigation, clavier, scroll et safe areas sur iPhone."],["Web","SEO et contenu","Titres, descriptions, canonical, sitemap, robots, liens et accessibilité. Vérifier catalogue, prix, provenance et droits des images.","Peut-on inventer un prix absent de la source ?","Non, signaler l’information manquante.","Oui, pour remplir la page.","Comparer un catalogue de test à sa source et relever les écarts."],["IA","Orchestration et contexte","Tickets bornés, contexte minimal, outils en moindre privilège, validation humaine des actions sensibles. Vérifier les sorties contre les sources.","Une réponse d’agent constitue-t-elle une autorisation ?","Non, elle reste un brouillon à vérifier.","Oui, si l’agent est spécialisé.","Écrire un ticket avec contraintes, critères et preuves attendues."],["IA","Routage local","Tester les modèles locaux isolément : qualité, latence, RAM, VRAM et erreurs. Ne pas annoncer de gains non mesurés.","Comment choisir un modèle local ?","Comparer des résultats mesurés sur des tâches représentatives.","Choisir selon une promesse marketing.","Préparer un protocole de benchmark reproductible."],["Qualité","Séquences et Quality Gate","Cadrage, recherche, architecture, menaces, DA, exploration, implémentation, motion, tests, red team, revue esthétique, livraison et exploitation.","Que faire si un test échoue ?","Revenir à l’étape concernée et corriger.","Compenser avec une meilleure note esthétique.","Transformer un besoin en ticket avec critères d’acceptation et tests."],["Données","Stockage et confidentialité","Classer les données, définir accès, rétention, suppression et sauvegarde. IndexedDB n’est pas un coffre-fort chiffré.","Stocker un token secret dans IndexedDB suffit-il ?","Non, le stockage local n’est pas un coffre-fort.","Oui, car il est hors ligne.","Lister les données d’une PWA et leur politique de conservation."],["Commerce","Paiements et conformité","Valider les montants côté serveur, utiliser des webhooks signés et idempotents, ne pas stocker les cartes. Vérifier les obligations sectorielles.","Le prix envoyé par le navigateur est-il fiable ?","Non, le serveur doit recalculer et valider.","Oui, si le bouton est protégé.","Définir les tests de montant modifié et de webhook répété."],["Knowledge","Capitalisation","Enregistrer source, date, observations, incertitudes, décision, test et preuve. Distinguer observation et recommandation.","Une vidéo partiellement lisible permet-elle un audit exhaustif ?","Non, documenter les limites.","Oui, si le titre est clair.","Créer une fiche source avec décision adopter, tester ou rejeter."],["AWS","Responsabilité partagée","AWS protège l’infrastructure physique ; le client reste responsable de ses données et de ses configurations selon le service.","Qui configure les droits IAM ?","Le client.","AWS exclusivement.","Comparer les responsabilités EC2 et S3.","https://aws.amazon.com/training/"],["AWS","Services cloud","EC2 fournit des machines virtuelles ; S3 stocke des objets ; RDS gère des bases relationnelles ; Lambda exécute des fonctions.","Quel service stocke des objets ?","S3.","EC2.","Dessiner une architecture web avec S3 et Lambda.","https://aws.amazon.com/training/"],["AWS","Coûts et disponibilité","Les régions regroupent des zones de disponibilité. Les budgets et alertes aident à suivre les dépenses sans garantir un plafond.","Une alerte budgétaire bloque-t-elle toujours les dépenses ?","Non.","Oui.","Comparer deux architectures sans créer de ressources facturables.","https://aws.amazon.com/training/"],["Azure","Modèles cloud","IaaS donne davantage de contrôle sur les machines ; PaaS délègue la plateforme ; SaaS fournit une application.","Une application de messagerie hébergée est généralement ?","SaaS.","IaaS.","Classer trois services selon leur modèle.","https://learn.microsoft.com/en-us/credentials/certifications/azure-fundamentals/"],["Azure","Organisation Azure","Les abonnements structurent la facturation et les limites ; les groupes de ressources organisent les ressources ; Azure Policy impose des règles.","Quel outil contrôle la conformité des configurations ?","Azure Policy.","Azure DNS.","Dessiner une hiérarchie de ressources.","https://learn.microsoft.com/en-us/credentials/certifications/azure-fundamentals/"],["Azure","Identité Azure","Microsoft Entra gère les identités ; Azure RBAC attribue des droits sur des ressources.","Quel principe limite les droits ?","Moindre privilège.","Administrateur global pour tous.","Définir des rôles lecteur et opérateur.","https://learn.microsoft.com/en-us/credentials/certifications/azure-fundamentals/"],["Sécurité Microsoft","Zero Trust","Vérifier explicitement, limiter les privilèges et supposer une compromission possible.","Un réseau interne suffit-il à établir la confiance ?","Non.","Oui.","Décrire un accès conditionnel.","https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/sc-900"],["Sécurité Microsoft","Entra et MFA","L’authentification établit une identité ; l’autorisation détermine les actions permises. MFA combine plusieurs facteurs.","Deux mots de passe constituent-ils deux facteurs ?","Non.","Oui.","Classer connaissance, possession et biométrie.","https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/sc-900"],["Sécurité Microsoft","Détection et conformité","Sentinel centralise l’analyse de sécurité ; Defender aide à protéger les actifs ; Purview aide à gouverner les données.","Quel outil relève principalement de la gouvernance des données ?","Purview.","Azure DNS.","Associer trois besoins aux outils.","https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/sc-900"],["Réseaux Cisco","IPv4 et sous-réseaux","Un préfixe /24 laisse huit bits pour les adresses d’hôtes. La passerelle achemine vers d’autres réseaux.","Quel équipement relie des réseaux IP ?","Routeur.","Hub.","Calculer réseau et broadcast de 192.168.1.42/24.","https://www.netacad.com/"],["Réseaux Cisco","DNS et DHCP","DHCP attribue des paramètres réseau ; DNS résout des noms.","Quel protocole distribue une adresse IP ?","DHCP.","DNS.","Diagnostiquer une adresse 169.254.x.x.","https://www.netacad.com/"],["Réseaux Cisco","TCP et UDP","TCP fournit un flux fiable et ordonné ; UDP transporte des datagrammes sans garantie intégrée de livraison.","Quel transport fournit des retransmissions intégrées ?","TCP.","UDP.","Comparer les usages DNS et HTTPS.","https://www.netacad.com/"],["IBM Cyber","Confidentialité intégrité disponibilité","La confidentialité limite la divulgation, l’intégrité protège contre les modifications non autorisées et la disponibilité garantit l’accès utile.","Une modification non autorisée affecte principalement ?","Intégrité.","Disponibilité.","Classer trois incidents.","https://skillsbuild.org/fr/learning-catalog"],["IBM Cyber","Réponse aux incidents","Préparer, détecter, analyser, contenir, rétablir et tirer les enseignements ; préserver les preuves.","Avant de supprimer un fichier suspect ?","Préserver les preuves selon procédure.","Effacer tous les journaux.","Écrire un ticket d’incident fictif.","https://skillsbuild.org/fr/learning-catalog"],["Linux","Permissions Unix","Les bits r,w,x s’appliquent au propriétaire, groupe et autres. chmod 640 donne lecture/écriture au propriétaire et lecture au groupe.","Que permet chmod 640 au groupe ?","Lecture.","Exécution.","Expliquer ls -l sur trois fichiers.","https://training.linuxfoundation.org/"],["Linux","Services Linux","systemctl status examine un service ; journalctl consulte ses journaux ; ps liste les processus.","Quel outil consulte les journaux systemd ?","journalctl.","chmod.","Diagnostiquer un service fictif.","https://training.linuxfoundation.org/"],["Data Engineering","Modèles de données","Un modèle relationnel représente des relations entre entités ; un document regroupe des données souvent lues ensemble. Choisir selon les accès et contraintes.","Une relation plusieurs-à-plusieurs est-elle naturellement représentable par une table de liaison ?","Oui.","Non.","Modéliser missions et compétences avec une table de liaison.","https://dataintensive.net/"],["Data Engineering","Index et structures","Un index accélère certaines lectures au prix de stockage et de maintenance en écriture. Les B-trees favorisent les parcours ordonnés ; les tables de hachage les recherches exactes.","Un index est-il gratuit en écriture ?","Non.","Oui.","Comparer recherche linéaire et index sur un jeu de données.","https://dataintensive.net/"],["Data Engineering","LSM et stockage","Les structures LSM regroupent les écritures puis fusionnent des segments ; la compaction entraîne un coût supplémentaire.","La compaction consomme-t-elle des ressources ?","Oui.","Non.","Dessiner le cycle mémoire, segments et fusion.","https://dataintensive.net/"],["Data Engineering","Transactions ACID","Atomicité, cohérence, isolation et durabilité décrivent des garanties distinctes. Une transaction atomique évite les modifications partielles.","Deux écritures indépendantes garantissent-elles une atomicité commune ?","Non.","Oui.","Simuler une erreur entre deux écritures dans une transaction de test.","https://dataintensive.net/"],["Data Engineering","Évolution des schémas","Une migration doit préserver les données existantes et tenir compte des anciennes versions du logiciel.","Faut-il tester une migration sur des données anciennes ?","Oui.","Non.","Préparer un jeu de données v1 et vérifier sa lecture après migration.","https://dataintensive.net/"],["Data Engineering","Réplication","La réplication maintient plusieurs copies ; une réplication asynchrone peut présenter un retard.","Une réplique asynchrone est-elle toujours à jour ?","Non.","Oui.","Dessiner une écriture suivie d'une lecture sur une réplique.","https://dataintensive.net/"],["Data Engineering","Partitionnement","Le partitionnement répartit les données ; une mauvaise clé peut concentrer la charge sur une partition.","Une clé très déséquilibrée peut-elle créer un point chaud ?","Oui.","Non.","Comparer partitionnement par utilisateur et par date.","https://dataintensive.net/"],["Data Engineering","Pannes distribuées","Une absence de réponse ne prouve pas que l'opération a échoué. Les délais et reprises doivent tenir compte des résultats incertains.","Un timeout prouve-t-il que le serveur n'a rien écrit ?","Non.","Oui.","Imaginer une réponse perdue après une écriture réussie.","https://dataintensive.net/"],["Data Engineering","Cohérence et consensus","La linéarisabilité impose une apparence d'ordre compatible avec le temps réel. Le consensus permet un accord sous des hypothèses de panne définies.","La cohérence éventuelle garantit-elle une lecture immédiatement à jour ?","Non.","Oui.","Comparer deux lectures après une écriture.","https://dataintensive.net/"],["Data Engineering","Événements et idempotence","Un identifiant stable permet de reconnaître un événement déjà traité. Un journal d'événements peut servir à reconstruire un état.","Une reprise doit-elle pouvoir éviter un double effet ?","Oui.","Non.","Concevoir un identifiant de publication quotidienne.","https://dataintensive.net/"],["Data Engineering","Batch et flux","Le batch traite un ensemble borné ; un flux traite des événements continus, parfois tardifs ou désordonnés.","Les événements arrivent-ils nécessairement dans leur ordre de création ?","Non.","Oui.","Dédupliquer un flux fictif d'actualités.","https://dataintensive.net/"],["Data Engineering","Local-first","Les données locales restent utilisables hors connexion ; la synchronisation éventuelle exige des règles de résolution des conflits.","Une copie locale est-elle automatiquement une sauvegarde indépendante ?","Non.","Oui.","Tester lecture hors ligne et export sur un appareil de test.","https://dataintensive.net/"],["Data Engineering","Sauvegarde et restauration","Une sauvegarde utile doit être restaurable. RPO mesure la perte temporelle tolérée ; RTO le délai de reprise visé.","Un export non testé garantit-il la restauration ?","Non.","Oui.","Restaurer un export fictif dans une base de test.","https://dataintensive.net/"],["Data Engineering","Fiabilité et performance","Mesurer latence, débit et erreurs selon des charges représentatives ; les percentiles révèlent les lenteurs masquées par la moyenne.","La moyenne suffit-elle à décrire les requêtes lentes ?","Non.","Oui.","Comparer médiane et p95 sur une série de durées.","https://dataintensive.net/"]];
function localizedLesson(i){return window.VEKAID_LESSON_PACKS?.[locale]?.[i]||generatedLessons.get(locale)?.[i]||academyLessons[i]}
const careerPaths=[["Support informatique","Windows · Linux · Active Directory","Documenter un dépannage reproductible.","Linux"],["Systèmes et réseaux","DNS · DHCP · VirtualBox","Configurer un réseau de laboratoire et vérifier DNS et DHCP.","DNS"],["Cloud et DevOps","Docker · Git · CI/CD","Construire un pipeline de test et de déploiement local.","Docker"],["Sécurité cloud et DevSecOps","IAM · CI/CD · Secrets","Vérifier les permissions et les secrets d’un pipeline de laboratoire.","Sécurité"],["Cybersécurité avancée","Pentest · GRC · Risk","Rédiger un rapport de risques sur un laboratoire autorisé.","Sécurité"]];
function careerCatalog(){const b=layer('Parcours métiers','Choisir un objectif professionnel','<div id="careerlist" class="v23-list"></div><button class="v23-btn" id="careerback">Retour à Academy</button>');for(const [name,skills,exercise,query] of careerPaths){const card=document.createElement('div');card.className='v23-card';const title=document.createElement('b');title.textContent=name;const tech=document.createElement('small');tech.textContent=skills;const p=document.createElement('p');p.textContent=exercise;const a=document.createElement('button');a.className='v23-btn';a.textContent='Explorer les cours';a.onclick=async()=>{closeLayer(b.closest('.v23-layer'));const input=$('.v23-layer:not([hidden]) #acq');if(input){input.value=query;input.dispatchEvent(new Event('input'))}};card.append(title,tech,p,a);$('#careerlist',b).append(card)}$('#careerback',b).onclick=()=>closeLayer(b.closest('.v23-layer'))}
function certificationCatalog(){const catalog=window.VEKAID_CERTIFICATIONS;if(!catalog)return;const b=layer('Certification Center',translateLabel('Formations, badges et certifications')+' · '+catalog.checked,'<p class="v23-note">Vérifie les conditions officielles avant inscription. Aucun paiement requis pour utiliser ce répertoire.</p><input class="v23-search" id="certq" placeholder="Rechercher une certification" aria-label="Rechercher une certification"><select class="v23-search" id="certfilter" aria-label="Type de formation"><option value="all">Toutes les ressources</option><option value="free">Qualifications et badges gratuits</option><option value="course">Cours et labs gratuits</option><option value="verify">À vérifier</option><option value="paid">Préparation gratuite, examen payant</option></select><p id="certcount" role="status"></p><div class="v23-list" id="certlist"></div><button class="v23-btn" id="certback">Retour à Academy</button>');const labels={certification:'Certification gratuite',qualification:'Qualification pratique',badge:'Badge / attestation de cours',course:'Cours ou lab gratuit',verify:'Conditions à vérifier',paid:'Examen payant'};const statuses={};try{Object.assign(statuses,JSON.parse(localStorage.getItem('vekaid.certifications.v1')||'{}'))}catch{}const draw=()=>{const q=$('#certq',b).value.trim().toLowerCase(),f=$('#certfilter',b).value,list=$('#certlist',b);list.replaceChildren();const items=catalog.items.filter(p=>(f==='all'||(f==='free'?['certification','qualification','badge'].includes(p.type):p.type===f))&&[p.name,p.domain,p.note].join(' ').toLowerCase().includes(q)).sort((a,z)=>a.priority-z.priority);$('#certcount',b).textContent=items.length+' '+translateLabel('ressources');for(const p of items){const z=document.createElement('article');z.className='v23-card cert-card';const title=document.createElement('strong');title.textContent=p.name;title.setAttribute('data-vek-user-content','');const note=document.createElement('p');note.textContent=translateLabel(labels[p.type])+' · '+translateLabel('Priorité')+' '+p.priority+' — '+translateLabel(p.note);const a=document.createElement('a');a.className='v23-btn primary';a.href=p.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=p.linkKind==='catalogue'?'Ouvrir le catalogue officiel':'Ouvrir la formation officielle';const copy=document.createElement('button');copy.className='v23-btn';copy.textContent='Copier le lien';copy.onclick=async()=>{try{await navigator.clipboard.writeText(p.url);copy.textContent='Lien copié'}catch{const t=document.createElement('input');t.value=p.url;t.readOnly=true;z.append(t);t.select()}};const status=document.createElement('select');status.className='v23-search';status.setAttribute('aria-label',translateLabel('Progression')+' '+p.name);for(const [v,l] of [['todo','À faire'],['doing','En cours'],['done','Terminé (déclaré)']]){const o=document.createElement('option');o.value=v;o.textContent=l;status.append(o)}status.value=['todo','doing','done'].includes(statuses[p.id])?statuses[p.id]:'todo';status.onchange=()=>{statuses[p.id]=status.value;try{localStorage.setItem('vekaid.certifications.v1',JSON.stringify(statuses))}catch{}};const review=document.createElement('button');review.className='v23-btn';review.textContent='Réviser dans Academy';review.onclick=async()=>{closeLayer(b.closest('.v23-layer'));const input=$('.v23-layer:not([hidden]) #acq');if(input){input.value=p.query;input.dispatchEvent(new Event('input'))}};z.append(title,note,a,copy,status,review);list.append(z)}};$('#certq',b).oninput=draw;$('#certfilter',b).onchange=draw;$('#certback',b).onclick=()=>closeLayer(b.closest('.v23-layer'));draw()}
async function academy(){const rows=await all('meta'),records=Object.fromEntries(rows.filter(x=>typeof x.id==='string'&&x.id.startsWith('academy:')).map(x=>[x.id.slice(8),x]));const now=Date.now(),due=academyLessons.map((_,i)=>i).filter(i=>!records[i]||records[i].due<=now);const b=layer('Academy','Cours, exercices et révisions hors connexion','<section class="v23-section"><p class="v23-section-title">Session quotidienne</p><div class="v23-group"><div class="v23-row"><strong>'+due.length+' fiches à réviser</strong><small>'+Object.keys(records).length+' / '+academyLessons.length+' étudiées · pas une certification</small></div></div><button class="v23-btn primary" id="acdaily">Commencer une révision</button></section><div class="academy-pathways"><button class="v23-btn" id="cert-open">Parcours certifications</button><button class="v23-btn" id="career-open">Parcours métiers</button></div><input class="v23-search" id="acq" placeholder="Rechercher une compétence" aria-label="Rechercher une compétence"><div class="v23-list" id="aclist"></div><button class="v23-btn" id="acback">Retour aux preuves</button>');b.classList.add('academy-home');const draw=()=>{const q=$('#acq',b).value.toLowerCase();$('#aclist',b).replaceChildren();academyLessons.forEach((original,i)=>{const x=localizedLesson(i);if(![...original,...x].join(' ').toLowerCase().includes(q))return;const z=document.createElement('button');z.className='v23-row';z.innerHTML='<strong>'+esc(x[1])+'</strong><small>'+esc(x[0])+' · '+translateLabel(records[i]?'Déjà étudiée':'À découvrir')+'</small>';z.onclick=()=>academyLesson(i,records[i]);$('#aclist',b).append(z)})};$('#cert-open',b).onclick=certificationCatalog;$('#career-open',b).onclick=careerCatalog;$('#acq',b).oninput=draw;$('#acdaily',b).onclick=()=>academyLesson(due[0]??0,records[due[0]??0]);$('#acback',b).onclick=()=>closeLayer(b.closest('.v23-layer'));draw()}
function academyLesson(i,prior){const x=localizedLesson(i),b=layer(x[1],x[0]+' · '+translateLabel('Fiche pédagogique'),'<section class="v23-section"><p class="v23-section-title">Comprendre</p><div class="v23-note">'+esc(x[2])+'</div></section><section class="v23-section"><p class="v23-section-title">Vérifier</p><p>'+esc(x[3])+'</p><div class="v23-list" id="acanswers"></div><p id="acfeedback" role="status"></p></section><section class="v23-section"><p class="v23-section-title">Pratiquer</p><div class="v23-note">'+esc(x[6])+'</div></section><button class="v23-btn" id="acreturn">Retour à Academy</button><p class="v23-note">'+esc(x[7]?'Source programme : '+x[7]+' · Questions originales non officielles.':'Source : référentiel universel VEKAID, 25/11/2026 ; exercices pédagogiques complémentaires.')+'</p>');b.classList.add('academy-detail');const answers=[{t:x[4],ok:true},{t:x[5],ok:false}];if(Math.random()<.5)answers.reverse();for(const a of answers){const z=document.createElement('button');z.className='v23-btn';z.textContent=a.t;z.onclick=async()=>{const buttons=[...$('#acanswers',b).querySelectorAll('button')];buttons.forEach(v=>v.disabled=true);const streak=a.ok?(prior?.streak||0)+1:0,days=a.ok?[1,3,7,14,30][Math.min(streak-1,4)]:0;try{await put('meta',{id:'academy:'+i,streak,due:Date.now()+days*86400000,reviewedAt:new Date().toISOString(),correct:a.ok});$('#acfeedback',b).textContent=(a.ok?(locale==='en'?'Correct. Next review in '+days+' day(s).':locale==='zh-Hans'?'正确。'+days+' 天后复习。':'Correct. Prochaine révision dans '+days+' jour(s).'):translateLabel('À revoir aujourd’hui.'))+' '+x[4]}catch(e){$('#acfeedback',b).textContent=translateLabel('Enregistrement impossible. Réessaie.');buttons.forEach(v=>v.disabled=false)}};$('#acanswers',b).append(z)}$('#acreturn',b).onclick=academy}

async function learn(){const p=await all('skills');const b=layer('Learn','Compétences fondées sur des preuves, pas sur une auto-certification','<section class="v23-section"><p class="v23-section-title">Academy</p><button class="v23-btn primary" id="academy-open">Ouvrir la bibliothèque & réviser</button></section><section class="v23-section"><p class="v23-section-title">Compétences suivies</p><div class="v23-group" id="sl"></div></section><div class="v23-note">Ici, une compétence sans preuve enregistrée n’est pas notée à zéro : elle est simplement non documentée dans VEKAID.</div><div id="se"></div>');$('#academy-open',b).onclick=academy;for(const s of skills){const items=p.filter(x=>x.skill===s),n=items.length,r=document.createElement('button');r.className='v23-row';const status=n?(n===1?'1 preuve enregistrée':n+' preuves enregistrées'):'À documenter';r.innerHTML='<strong>'+esc(s)+'</strong><small>'+status+'</small>';r.onclick=()=>proofForm(b,s,items);$('#sl',b).append(r)}}
function proofForm(b,s,items){$('#se',b).innerHTML=`<form id="pf" novalidate><section class="v23-form-chunk"><p class="v23-section-title">Documenter la preuve</p><div class="v23-field"><label>Type</label><select name="source"><option>Lab reproductible</option><option>Git / PR</option><option>Test</option><option>Projet</option><option>Explication technique</option></select></div><div class="v23-field"><label>Ce que la preuve démontre</label><textarea name="proof"></textarea><span class="v23-field-hint">Décris un résultat observable, pas une auto-évaluation.</span></div><div class="v23-field"><label>Référence</label><input name="ref" placeholder="URL, commit, fichier ou note"></div></section><button type="submit" class="v23-btn primary">Enregistrer la preuve</button></form><div class="v23-list">${items.length?items.map(x=>'<div class="v23-card"><b>'+esc(x.source)+'</b><small>'+esc(x.proof)+'</small></div>').join(''):'<div class="v23-empty">Aucune preuve enregistrée pour cette compétence. Cela ne signifie pas que ton niveau est nul : VEKAID n’a simplement encore aucune preuve documentée ici.<button type="button" class="v23-btn" data-focus-proof>Ajouter une première preuve</button></div>'}</div>`;enhanceVekForm($('#pf',b),{requiredName:'proof',readyText:'Preuve suffisamment décrite',errorText:'Décris ce que cette preuve démontre'});b.querySelector('[data-focus-proof]')?.addEventListener('click',()=>{const el=b.querySelector('#pf textarea[name="proof"]');el?.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>el?.focus(),260)});$('#pf',b).onsubmit=async e=>{e.preventDefault();if(e.currentTarget.__vekValidate&&!e.currentTarget.__vekValidate())return;const done=submitState(e.currentTarget,'Enregistrement…');const f=new FormData(e.currentTarget);try{await put('skills',{id:uid(),skill:s,source:String(f.get('source')),proof:String(f.get('proof')).trim(),ref:String(f.get('ref')).trim(),createdAt:new Date().toISOString()});done(true);setTimeout(learn,480)}catch(err){done(false)}}}

